:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --green: #4ecca3;
  --too-soon: #ff6b6b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 3px solid var(--primary);
  border-radius: 12px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 12px;
  color: var(--accent);
  letter-spacing: 1px;
}

.instructions {
  margin-bottom: 24px;
  line-height: 1.5;
  opacity: 0.9;
}

.game-area {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  margin-bottom: 24px;
}

.btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: #ff5c7a;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.97);
}

.reaction-box {
  width: 100%;
  min-height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  border: 3px solid var(--accent);
  border-radius: 12px;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s, border-color 0.15s;
  padding: 16px;
}

.reaction-box:hover {
  border-color: var(--text);
}

.reaction-box:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.reaction-box.waiting {
  background: var(--primary);
  border-color: var(--accent);
  cursor: wait;
}

.reaction-box.green {
  background: var(--green);
  border-color: var(--green);
  color: #0a0a0a;
  cursor: pointer;
}

.reaction-box.too-soon {
  background: var(--too-soon);
  border-color: var(--too-soon);
  color: #0a0a0a;
}

.info {
  display: flex;
  justify-content: space-around;
  gap: 16px;
  margin-bottom: 16px;
  font-size: 1.1rem;
}

.status {
  min-height: 1.5em;
  font-weight: bold;
  color: var(--accent);
}

@media (max-width: 400px) {
  body {
    font-size: 16px;
  }
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .reaction-box {
    min-height: 120px;
    font-size: 1rem;
  }
  .info {
    flex-direction: column;
    gap: 8px;
  }
}

(function () {
  'use strict';

  const startBtn = document.getElementById('startBtn');
  const reactionBox = document.getElementById('reactionBox');
  const boxText = document.getElementById('boxText');
  const timeDisplay = document.getElementById('timeDisplay');
  const bestDisplay = document.getElementById('bestDisplay');
  const statusEl = document.getElementById('status');

  let state = 'idle'; // idle | waiting | green | too-soon | done
  let timeoutId = null;
  let startTime = 0;
  let bestTime = null;

  // Load best time from localStorage with fallback
  try {
    const stored = localStorage.getItem('pixelReactionBest');
    if (stored !== null) {
      const parsed = parseInt(stored, 10);
      if (!isNaN(parsed)) {
        bestTime = parsed;
        bestDisplay.textContent = bestTime;
      }
    }
  } catch (e) {
    // localStorage unavailable (file:// or privacy mode) – ignore
  }

  function setState(newState) {
    state = newState;
    reactionBox.className = 'reaction-box';
    reactionBox.setAttribute('aria-label', 'Reaction box');
    switch (newState) {
      case 'idle':
        boxText.textContent = 'Click Start';
        break;
      case 'waiting':
        reactionBox.classList.add('waiting');
        boxText.textContent = 'Wait for green…';
        reactionBox.setAttribute('aria-label', 'Waiting for green. Do not click yet.');
        break;
      case 'green':
        reactionBox.classList.add('green');
        boxText.textContent = 'CLICK!';
        reactionBox.setAttribute('aria-label', 'Green! Click or press Enter now.');
        break;
      case 'too-soon':
        reactionBox.classList.add('too-soon');
        boxText.textContent = 'Too soon!';
        reactionBox.setAttribute('aria-label', 'Too soon. Click Start to try again.');
        break;
      case 'done':
        boxText.textContent = 'Click Start again';
        break;
    }
  }

  function resetGame() {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    startTime = 0;
    timeDisplay.textContent = '—';
    statusEl.textContent = '';
    setState('idle');
  }

  function startGame() {
    resetGame();
    setState('waiting');
    statusEl.textContent = 'Wait for the box to turn green…';
    const delay = 1000 + Math.random() * 4000; // 1–5 seconds
    timeoutId = setTimeout(function () {
      timeoutId = null;
      if (state !== 'waiting') return; // safety
      startTime = performance.now();
      setState('green');
      statusEl.textContent = 'Click now!';
    }, delay);
  }

  function handleReaction() {
    if (state === 'waiting') {
      // Early click
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      setState('too-soon');
      statusEl.textContent = 'Too soon! Wait for green.';
      return;
    }
    if (state === 'green') {
      const elapsed = Math.round(performance.now() - startTime);
      timeDisplay.textContent = elapsed;
      statusEl.textContent = 'Your time: ' + elapsed + ' ms';
      setState('done');
      // Update best time
      if (bestTime === null || elapsed < bestTime) {
        bestTime = elapsed;
        bestDisplay.textContent = bestTime;
        statusEl.textContent = 'New best: ' + elapsed + ' ms!';
        try {
          localStorage.setItem('pixelReactionBest', String(bestTime));
        } catch (e) {
          // localStorage unavailable – best time kept in memory only
        }
      }
      return;
    }
    // idle, done, too-soon – ignore
  }

  startBtn.addEventListener('click', startGame);

  reactionBox.addEventListener('click', handleReaction);

  reactionBox.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleReaction();
    }
  });

  // Initial state
  setState('idle');
})();
